function formatEmailFrom(from) {
  if (!from) return 'Unknown sender';
  if (typeof from === 'string') return from;
  if (from.text) return from.text;
  if (Array.isArray(from.value) && from.value[0]) {
    const v = from.value[0];
    if (v.name && v.address) return `${v.name} <${v.address}>`;
    return v.address || v.name || 'Unknown sender';
  }
  return 'Unknown sender';
}

function candidateFromFileName(fileName) {
  if (!fileName) return 'Unknown Candidate';
  return fileName
    .replace(/\.(pdf|docx?|PDF|DOCX?)$/,'')
    .replace(/[-_]+/g, ' ')
    .replace(/\bresume\b/gi, '')
    .replace(/\bcv\b/gi, '')
    .replace(/\s+/g, ' ')
    .trim() || 'Unknown Candidate';
}

const items = [];

for (const item of $input.all()) {
  const binary = item.binary || {};
  const keys = Object.keys(binary);

  for (const key of keys) {
    if (!key.startsWith('attachment_')) continue;

    const file = binary[key];
    const lowerName = (file.fileName || key).toLowerCase();
    const mime = (file.mimeType || '').toLowerCase();

    const isResume =
      lowerName.endsWith('.pdf') ||
      lowerName.endsWith('.docx') ||
      lowerName.endsWith('.doc') ||
      mime.includes('pdf') ||
      mime.includes('word') ||
      mime.includes('document');

    if (!isResume) continue;

    const fileName = file.fileName || key;

    items.push({
      json: {
        emailSubject: item.json.subject || '(no subject)',
        emailFrom: formatEmailFrom(item.json.from || item.json.From),
        fileName,
        candidateName: candidateFromFileName(fileName),
      },
      binary: {
        data: file,
      },
    });
  }
}

return items;

const token = $('Login HireFlow').first().json.access_token;

if (!token) {
  throw new Error('Login failed — no access_token. Check email/password in Login HireFlow node.');
}

return $('Extract Resume Attachments').all().map((item) => ({
  json: {
    ...item.json,
    access_token: token,
  },
  binary: item.binary,
}));

const token = $('Attach Token + Resume').first().json.access_token;
const resume = $input.first().json;

if (!resume?.id) {
  throw new Error('Upload failed — no resume id');
}

return [{
  json: {
    ...resume,
    access_token: token,
    fileName: $('Attach Token + Resume').first().json.fileName,
    emailFrom: $('Attach Token + Resume').first().json.emailFrom,
    emailSubject: $('Attach Token + Resume').first().json.emailSubject,
    candidateName: $('Attach Token + Resume').first().json.candidateName,
  },
}];

const data = $input.first().json;
const emailMeta = $('Prepare Auto Match').first().json;

const candidateName =
  data.candidate_name ||
  emailMeta.candidateName ||
  'Unknown Candidate';

const best = data.best_job || {};
const qualified = Array.isArray(data.qualified_jobs) ? data.qualified_jobs : [];
const threshold = data.score_threshold ?? 50;

const bestMatched = (best.matched_skills || []).slice(0, 10).join(', ') || 'N/A';
const bestMissing = (best.missing_skills || []).slice(0, 8).join(', ') || 'None';

const jobLines = qualified.map((j, idx) => {
  return `${idx + 1}. *${j.job_title}* @ ${j.company} — *${j.match_score}%*`;
});

const text = [
  `<!channel>`,
  ``,
  `👋 *Dear HR Team,*`,
  ``,
  `A new candidate resume just landed in HireFlow and has been screened against our open roles.`,
  ``,
  `*Candidate:* ${candidateName}`,
  `*Resume file:* ${data.resume_filename || emailMeta.fileName || 'N/A'}`,
  `*Received from:* ${emailMeta.emailFrom || 'N/A'}`,
  `*Email subject:* ${emailMeta.emailSubject || '(no subject)'}`,
  `*Resume ID:* \`${data.resume_id || ''}\``,
  ``,
  `*Best matched job*`,
  `• *${best.job_title || 'N/A'}* @ ${best.company || 'N/A'}`,
  `  Match score: *${best.match_score ?? 'N/A'}%*`,
  `  Matched skills: ${bestMatched}`,
  `  Missing skills: ${bestMissing}`,
  best.summary ? `  Summary: ${best.summary}` : null,
  ``,
  `*Jobs this candidate qualifies for (score ≥ ${threshold}):*`,
  ...(jobLines.length ? jobLines : ['None']),
  ``,
  `_Please review this candidate and proceed with shortlisting if it looks like a fit._`,
].filter((line) => line !== null).join('\n');

return [{
  json: {
    text,
    candidateName,
    best_score: best.match_score,
    qualified_count: qualified.length,
  },
}];

const err = $input.first().json;
const msg = err.message || err.error || JSON.stringify(err);
const node = err.node?.name || err.node || 'Unknown node';

const text = [
  `<!channel>`,
  ``,
  `🚨 *HireFlow Automation Failed*`,
  ``,
  `*Node:* ${node}`,
  `*Error:* ${msg}`,
  `*Time:* ${new Date().toISOString()}`,
  ``,
  `_Please check n8n Executions and backend logs._`,
].join('\n');

return [{ json: { text } }];
